import { describe, expect, it } from 'vitest';
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

/**
 * The brand bridge in theme.css re-declares Untitled UI's brand chain on the component
 * root (see the comment above it). It is generated by `scripts/brand-bridge.mjs`; these
 * tests run the generator's own `--check`, so a resync of uui-theme.css that adds a brand
 * token fails here until the block is regenerated.
 */

const root = join(__dirname, '..', '..', '..');
const themeCss = readFileSync(join(root, 'resources/js/styles/theme.css'), 'utf8');
const block = themeCss.slice(themeCss.indexOf('/* brand-bridge:begin'), themeCss.indexOf('/* brand-bridge:end */'));

describe('brand bridge', () => {
  it('is present and of a plausible size', () => {
    // A floor, so a parse that found nothing cannot pass by having nothing to compare.
    const count = (block.match(/^\s+--[\w-]+:/gm) ?? []).length;
    expect(count).toBeGreaterThanOrEqual(50);
  });

  it('covers the tokens the brand utilities actually read', () => {
    // `bg-brand-solid` compiles to var(--background-color-brand-solid), and so on.
    for (const t of [
      '--background-color-brand-solid',
      '--background-color-brand-solid_hover',
      '--text-color-brand-secondary',
      '--border-color-brand',
      '--ring-color-brand',
      '--outline-color-brand',
      '--color-focus-ring',
      '--color-slider-handle-border',
    ]) {
      expect(block, t).toContain(`${t}:`);
    }
  });

  it('stays at zero specificity, so the dark theme still wins', () => {
    expect(block).toContain(':where([data-ichava-theme])');
    expect(block).toContain('@layer base');
  });

  it('matches what the generator derives from uui-theme.css', () => {
    expect(() =>
      execFileSync(process.execPath, [join(root, '.dev/browser/brand-bridge.mjs'), '--check'], { stdio: 'pipe' }),
    ).not.toThrow();
  });
});
